171:     @Override
172:     public Object get(CompoundName key,
173:                       Map<String, String> context,
174:                       com.yahoo.processing.request.Properties substitution) {
175:         GetterSetter propertyAccessor = propertyAccessors.get(key);
176:         if (propertyAccessor != null && propertyAccessor.getter != null) return propertyAccessor.getter.get(query);
177: 
178:         if (key.first().equals(Ranking.RANKING)) {
179:             Ranking ranking = query.getRanking();
180:             if (key.size() > 2) {
181:                 // pass the portion after "ranking.features/properties" down
182:                 if (key.get(1).equals(Ranking.FEATURES)) return ranking.getFeatures().getObject(key.rest().rest().toString());
183:                 if (key.get(1).equals(Ranking.PROPERTIES)) return ranking.getProperties().get(key.rest().rest().toString());
184:             }
185:         }
186: 
187:         return super.get(key, context, substitution);
188:     }
