190:     private void setInternal(CompoundName key, Object value, Map<String,String> context) {
191:         GetterSetter propertyAccessor = propertyAccessors.get(key);
192:         if (propertyAccessor != null && propertyAccessor.setter != null) {
193:             propertyAccessor.setter.set(query, value);
194:             return;
195:         }
196: 
197:         if (key.first().equals(Ranking.RANKING)) {
198:             if (key.size() > 2) {
199:                 String restKey = key.rest().rest().toString();
200:                 chained().requireSettable(key, value, context);
201:                 if (key.get(1).equals(Ranking.FEATURES)) {
202:                     setRankFeature(query, restKey, toSpecifiedType(restKey, value,
203:                             profileRegistry.getTypeRegistry().getComponent("features"),
204:                             context));
205:                     return;
206:                 } else if (key.get(1).equals(Ranking.PROPERTIES)) {
207:                     Ranking ranking = query.getRanking();
208:                     ranking.getProperties().put(restKey, toSpecifiedType(restKey, value,
209:                             profileRegistry.getTypeRegistry().getComponent("properties"),
210:                             context));
211:                     return;
212:                 }
213:             }
214:         }
215:         if (reservedPrefix.contains(key.first())) {
216:             // Setting a property under the reserved paths are illegal, while retrieving(get) one is not.
217:             throwIllegalParameter(key.rest().toString(), key.first());
218:         } else {
219:             super.set(key, value, context);
220:         }
221:     }
