223:     @Override
224:     public void set(CompoundName key, Object value, Map<String,String> context) {
225:         // Note: The defaults here are never used
226:         try {
227:             setInternal(key, value, context);
228:         }
229:         catch (Exception e) { // Make sure error messages are informative. This should be moved out of this properties implementation
230:             if (e.getMessage() != null && e.getMessage().startsWith("Could not set"))
231:                 throw e;
232:             else
233:                 throw new IllegalInputException("Could not set '" + key + "' to '" + value + "'", e);
234:         }
235:     }
