251:     private void setRankFeature(Query query, String key, Object value) {
252:         if (value instanceof Tensor) {
253:             query.getRanking().getFeatures().put(key, (Tensor) value);
254:         }
255:         else if (value instanceof Double) {
256:             query.getRanking().getFeatures().put(key, (Double) value);
257:         }
258:         else {
259:             String valueString = asString(value, "");
260:             try {
261:                 query.getRanking().getFeatures().put(key, Double.parseDouble(valueString));
262:             }
263:             catch (IllegalArgumentException e) {
264:                 query.getRanking().getFeatures().put(key, valueString);
265:             }
266:         }
267:     }
