269:     private Object toSpecifiedType(String key, Object value, QueryProfileType type, Map<String,String> context) {
270:         if ( ! ( value instanceof String)) return value; // already typed
271:         if (type == null) return value; // no type info -> keep as string
272:         FieldDescription field = type.getField(key);
273:         if (field == null) return value; // ditto
274:         return field.getType().convertFrom(value, new ConversionContext(key, profileRegistry, embedders, context, this));
275:     }
